"""billing's own version helpers (copy #2, forked from ingest's, then diverged)."""


def version_key(text):
    head = text.split("+")[0].split("-")[0]
    return tuple(int(p) for p in head.split("."))


def satisfies(version, spec):
    v = version_key(version)
    for token in spec.split(" "):
        if token[:2] in (">=", "<="):
            op, body = token[:2], token[2:]
        elif token[:1] in (">", "<"):
            op, body = token[:1], token[1:]
        else:
            op, body = "=", token
        k = version_key(body)
        if op == ">=" and not v >= k:
            return False
        if op == ">" and not v > k:
            return False
        if op == "<=" and not v <= k:
            return False
        if op == "<" and not v < k:
            return False
        if op == "=" and v != k:
            return False
    return True

