"""ingest's own version helpers (copy #1, written first, never revisited)."""


def version_key(text):
    head = text.split("+")[0].split("-")[0]
    return tuple(int(p) for p in head.split("."))


def satisfies(version, spec):
    v = version_key(version)
    if spec.startswith("^"):
        base = version_key(spec[1:])
        return base <= v < (base[0] + 1, 0, 0)
    return v == version_key(spec)

