"""The version badge printed at the top of every report."""
from .util import satisfies, version_key


def badge(versions, spec):
    hits = sorted((v for v in versions if satisfies(v, spec)), key=version_key)
    return "%s -> %s" % (spec, hits[-1] if hits else "none")

