"""reports' own version helpers (copy #3, pasted from billing, wildcards bolted on)."""


def version_key(text):
    head = text.split("+")[0].split("-")[0]
    return tuple(int(p) for p in head.split("."))


def satisfies(version, spec):
    v = version_key(version)
    if spec == "*":
        return True
    if spec.endswith(".x"):
        prefix = tuple(int(p) for p in spec[:-2].split("."))
        return v[:len(prefix)] == prefix
    return v == version_key(spec)

