"""FROZEN service tests. Do not edit. These pass TODAY and must still pass afterwards:
the three services keep their public functions and their behaviour on these inputs.
"""
import unittest

from billing.quota import allowed
from ingest.resolver import pick
from reports.render import badge

RELEASES = ["1.2.3", "1.2.7", "1.2.10", "1.3.0", "2.0.0", "2.1.0", "10.0.0"]


class TestIngest(unittest.TestCase):
    def test_caret_picks_the_newest_compatible(self):
        self.assertEqual(pick(RELEASES, "^1.2.3"), "1.3.0")

    def test_exact_pin(self):
        self.assertEqual(pick(RELEASES, "1.2.7"), "1.2.7")

    def test_nothing_matches(self):
        self.assertIsNone(pick(RELEASES, "^3.0.0"))

    def test_numeric_not_lexical(self):
        self.assertEqual(pick(RELEASES, "^1.0.0"), "1.3.0")


class TestBilling(unittest.TestCase):
    def test_window(self):
        self.assertTrue(allowed("1.5.0", ">=1.2.0 <2.0.0"))
        self.assertFalse(allowed("2.0.0", ">=1.2.0 <2.0.0"))
        self.assertTrue(allowed("2.0.0", ">=1.2.0 <=2.0.0"))

    def test_open_ended(self):
        self.assertTrue(allowed("10.0.0", ">1.2.3"))
        self.assertFalse(allowed("1.2.3", ">1.2.3"))


class TestReports(unittest.TestCase):
    def test_minor_wildcard(self):
        self.assertEqual(badge(RELEASES, "1.2.x"), "1.2.x -> 1.2.10")

    def test_star(self):
        self.assertEqual(badge(RELEASES, "*"), "* -> 10.0.0")

    def test_none(self):
        self.assertEqual(badge(RELEASES, "9.9.x"), "9.9.x -> none")


if __name__ == "__main__":
    unittest.main()

